        "step2_projection": "第二步·投射到领域:放到你『知道不对却一直拖』的状态上——你正活在逆位死神里:转化的时机已经到了(你自己都知道『不对了』),但恐惧让你抓着旧壳不放。死神指出:拖延不会让旧的复活,只会延长破茧的痛。",
