        "question": "我做了很多年的工作最近让我很痛苦，但我不确定是不是该彻底换个方向？",
        "domain": "career",
        "step1_energy": "第一步·抓核心能量：审判的核心是「听见召唤、诚实清算、然后重生」。它不是问你「哪条路更划算」，而是问你「你灵魂深处真正被召唤去做的是什么」，并要求你先对走过的路做一次坦诚的回顾。",
        "step2_projection": "第二步·投射到领域：放到你的职业困境上——你的痛苦其实就是那声号角，是内心在告诉你「这个旧版本的活法不再适合你了」。审判在说：这不是要不要跳槽的技术问题，而是一次天职层面的觉醒信号，你已经听见了，只是还没敢应答。",
        "step3_action": "第三步·落地建议：给你的具体行动是——先做一次诚实的「职业清算」：把这些年做过的事全摊开，标出哪些让你活过来、哪些在消耗你，问自己「如果没人评判，我真正想被召唤去做什么」。这个答案会指向方向。然后出棺材的第一步不必是裸辞，可以是一次和该领域前辈的对话、一个探索性的小项目。关键是别再假装没听见那声号角。"
