    "applications": {
      "career": {
        "upright": "事业上是明确的成功信号：项目顺利、获得认可、升职加薪、面试通过。太阳正位说你正处在能量最饱满、最被看见的阶段，你的努力开始结出可见的果实。具体建议——大方展示你的成果、接受赞美别谦虚过头，趁这股清明和活力去推进你真正在意的事，别把功劳藏在阴影里。",
        "reversed": "成功可能延迟或被打折：好消息迟迟不来、成果没得到应有的认可、或者你自己因为不自信而不敢争取。也可能是虚假的繁荣——表面风光，你心里清楚有问题被回避了。逆位提醒你：先诚实面对被云挡住的那部分，光才照得进来。"
      },
      "love": {
        "upright": "感情里是极好的牌：关系明朗、温暖、充满玩心与坦诚。没有猜忌和隐藏，双方都能做真实的自己。对单身者，是一段阳光般轻松愉快的相遇；对伴侣，可能预示订婚、怀孕、或一起进入一个更幸福的阶段。建议——把爱大方说出来、一起晒晒太阳做点开心的事。",
        "reversed": "快乐还在，只是蒙了层薄云：可能是一方过度乐观、忽视了关系里真实的问题；或者你太怕破坏气氛而不敢坦诚。也可能是短暂的低气压——感情本身没坏，只是你一时看不到它的好。别急着悲观，先把话摊到阳光下说清楚。"
      },
      "self": {
        "upright": "在自我层面，太阳是「做真实的你，并且为此高兴」。它代表自我接纳、活力回归、内在小孩被点亮——你不再需要伪装或防备，可以坦荡地存在。鼓励你去做那些让你发自内心快乐的事，把你的天赋和热情大大方方展现出来，你的光本就该被看见。",
        "reversed": "你可能正压抑着自己的光——因为怕张扬、怕失望、或长期的自我怀疑，让本该闪耀的你缩了起来。也可能是用强颜欢笑掩盖真实感受。逆位在温柔地问：你是不是在为了别人而调暗自己？允许自己重新亮起来。"
      },
      "money": {
        "upright": "财务上是丰盛和顺遂的信号：收入增长、投资回报、财务状况清晰明朗。太阳的钱是「光明正大赚来、可以安心享受」的钱。建议——你可以适度地为快乐花钱、犒赏自己，同时因为一切都摆在明处，也是做长期规划的好时机。",
        "reversed": "丰盛还在路上，只是慢了一拍，或者你因为焦虑而享受不了已有的富足。也可能是过度乐观导致的盲目乐观消费——只看得到进账，没算清支出。逆位提醒：把财务的云推开，看清全貌，好消息才踏实。"
      }
    },
