    "translationDemos": [
      {
        "question": "我拿到了梦寐以求的 offer，却总有种「这么顺利是不是不真实」的不安，我该怎么想？",
        "domain": "career",
        "step1_energy": "第一步·抓核心能量：太阳的核心是「拨云见日的坦然喜悦」——真相被照亮、成功真实可见，唯一的功课是别用怀疑给这份好打折。它几乎是纯正向的能量：你值得，而且现在就可以享受。",
        "step2_projection": "第二步·投射到领域：把这股能量放到「拿到梦想 offer 却不安」上——牌在说，这份成功是货真价实的，不是你运气好或者搞错了，是你的努力被看见后结出的果。你的不安不是来自现实的危险，而是来自那种「不敢太开心怕乐极生悲」的自我设限（这正是太阳逆位的味道）。",
        "step3_action": "第三步·落地建议：所以给你的具体行动是——先明确地、认真地恭喜自己一次，把这个 offer 当成实力的证明而不是意外。写下你为它做过的所有努力，用事实反驳「不真实」的错觉。然后大方接住它：告诉信任的人、好好庆祝一下。把内在的光照出来，别急着躲回云后面。"
      },
      {
        "question": "我和伴侣现在相处得特别开心轻松，但我有点怕这只是暂时的，该不该多想一点？",
        "domain": "love",
        "step1_energy": "第一步·抓核心能量：太阳是坦诚、温暖、充满玩心的当下之乐——它代表关系此刻明朗、双方都能做真实的自己，没有隐藏和猜忌。",
        "step2_projection": "第二步·投射到领域：放到你们的关系上——太阳正位在确认：你们现在的这份轻松快乐是真的，不是假象，是值得珍惜和信任的好状态。你「怕它是暂时的」这个念头，本身就是逆位那朵想遮住阳光的云。",
        "step3_action": "第三步·落地建议：给你的行动是——先停止用「万一以后」去污染「现在很好」。太阳教的是活在当下的阳光里。具体做法：和伴侣一起做点纯粹开心的事（一次没有目的的短途出游、一顿慢慢吃的饭），把快乐坐实成共同记忆。如果心里真有担忧，就坦诚地摊到阳光下和 TA 聊，而不是自己在心里预演坏结局。"
      }
    ],
