        "reversed": "关系停在「差一点」的状态——想定下来却总缺临门一脚，或者一段该结束的关系拖着不肯正式告别。也可能是表面圆满、内里并不满足。逆位邀请你看清：你是在等一个真正的闭环，还是在害怕结束后的空白？"
