        "step3_action": "第三步·落地建议：所以给你的行动是——允许自己一小步一小步地重新敞开，而不是等『完全不怕了』才开始（那一天不会来）。先让这份心动被你自己承认和珍惜，再以你能承受的节奏靠近。圣杯一不保证结果，但它相信：把心关上，你挡掉的不只是伤害，还有所有本可流进来的爱。"
