        "step2_projection": "第二步·投射到领域：放到你『心里空空、提不起感情』的状态上——你可能正处在圣杯一的逆位：那口本该满溢的情感之泉，此刻堵住或干涸了。空虚往往不是因为没有爱，而是通向内心的管道被关上了。",
        "step3_action": "第三步·落地建议：给你的行动是——先不急着向外找填补（那容易变成消费或依赖），而是重新打开与自己内心的连接：做一点滋养情感的小事（独处、创作、与信任的人真诚聊聊、亲近自然），让情感的水重新流动起来。圣杯一提醒：泉眼在你自己心里，先让它重新涌出，空虚才会被真正填满。"
