        "step2_projection": "第二步·投射到领域：放到你『反复后悔』的循环上——你正卡在圣杯五的正位里，盯着那只打翻的杯一遍遍重放。悔恨的痛在于：你在用现在的眼光审判过去那个信息不全的自己，而那杯已经打翻，再看多久也扶不起来。",
        "step3_action": "第三步·落地建议：给你的行动是——练习圣杯五逆位的功课：自我宽恕。提醒自己当时的你是带着当时的认知做的选择，而非故意犯错。把『如果当初』的能量，转成『从这件事我学到了什么、现在我能做什么』。桥通向的是前方，不是回头——放下不是否认遗憾，而是决定不再让它占满你全部的视线。"
