      {
        "question": "我最近特别怀念过去（老朋友/以前的日子），这种情绪是好是坏？",
        "domain": "self",
        "step1_energy": "第一步·抓核心能量：圣杯六是『纯真的给予与美好的旧日记忆』——它是疗愈性的怀旧，让你重新连接单纯的温暖，但也提醒别永远活在过去。",
        "step2_projection": "第二步·投射到领域：放到你『特别怀念过去』的情绪上——圣杯六告诉你，这份怀旧本身是温柔而有疗愈力的（正位），尤其在你需要安慰时，旧日的美好像装满花的杯，能滋养当下的你。关键只在于：你是『汲取温暖后回到现在』，还是『躲进过去不肯出来』（逆位）。",
        "step3_action": "第三步·落地建议：所以给你的行动是——大方地享受这份怀旧：联系一位老朋友、翻翻旧照片、重温一件小时候喜欢的事，让那份单纯的温暖滋养你。同时给它一个『出口』：把旧日的美好当成补给，而不是避难所。如果发现自己是在用『过去多好』逃避现在的某个难题，那才是需要温柔提醒自己走回当下的信号。"
      },
      {
        "question": "前任突然联系我，勾起很多回忆，我该重新考虑复合吗？",
        "domain": "love",
        "step1_energy": "第一步·抓核心能量：圣杯六既是旧情重燃、纯真美好的回忆，其逆位也正是『放不下前任、活在旧关系的滤镜里』。",
        "step2_projection": "第二步·投射到领域：放到你被勾起回忆的处境上——圣杯六提醒你一个关键区分：你怀念的，是『真实的这个人和这段关系』，还是『被时间美化过的旧日滤镜』？花杯里装的是被珍藏、被理想化的记忆，未必等于现实。",
        "step3_action": "第三步·落地建议：给你的行动是——先分清『怀念那份感觉』和『想要那个真实的人』是两回事。诚实回想：当初结束是有真实原因的吗？那些原因现在变了吗？如果只是孤独或怀旧驱动（圣杯六的滤镜），别急着复合；如果双方都真实成长、问题确实解决了，再谨慎重新了解。别让美化的旧日回忆替你做决定。"
      }
