        "step2_projection": "第二步·投射到领域：放到你的心动上——圣杯七恰恰把朋友的提醒放大了：云中的杯装的是你投射的美好想象，而真实的人站在云雾之外。这张牌不是说你的感情假，而是提醒你——你可能还没分清『真实的他』和『你脑补的他』。",
        "step3_action": "第三步·落地建议：给你的行动是——让这段感情『落地』检验：多和真实的对方相处、了解他不完美的日常一面，看你的心动是否经得起现实的照面。如果了解越深越喜欢，那是真的；如果一接触真实就幻灭，那你爱的确实是云中那只杯。圣杯七要你做的，是走近去看清，而不是继续在想象里恋爱。"
