        "step2_projection": "第二步·投射到领域：放到你『稳定但内心空、想离开』的处境上——圣杯八几乎是为你量身画的：身后八只杯排得整整齐齐（你稳定的生活），别人看都觉得完整，但你知道其中缺了一个口。这张牌郑重地告诉你：你不是『作』，那种『够用却不够』的空，是真实且值得认真对待的信号。",
        "step3_action": "第三步·落地建议：所以给你的行动是——先分清这是圣杯八的正位（内心深处清醒地知道该追寻更有意义的东西）还是逆位（只是一时的逃避冲动，走到哪都会空）。如果这份『空』长期、稳定、指向明确的渴望，那圣杯八支持你勇敢规划转身——不必等到现状『变糟』才允许自己离开。同时它也提醒：离开要奔向意义，而不只是逃离，先想清楚你走向的那座山是什么。"
