        "step1_energy": "第一步·抓核心能量：圣杯八正位是勇敢地离开不再滋养你的关系，而逆位正是『害怕孤单而留在不满足里、明知该走却一直拖』。",
        "step2_projection": "第二步·投射到领域：放到你『知道不适合却怕孤单』的处境上——你正卡在圣杯八的逆位：内心那个拄杖的人已经想转身了，但对孤单的恐惧像一根绳子把你拴在那八只杯旁边。拖着的痛苦，往往比离开的痛苦更漫长。",
        "step3_action": "第三步·落地建议：给你的行动是——把恐惧和判断分开看：你判断『不适合』如果是清醒且长期的，那它是对的；而『怕孤单』是情绪，不该替你做决定。圣杯八提醒：留在一段填不满你的关系里，其实是另一种更深的孤单。给自己一个具体的、温柔但坚定的离开计划（而不是继续无限期拖），先照顾好离开后如何不孤单，再迈出那一步。"
