        "domain": "self",
        "step1_energy": "第一步·抓核心能量：圣杯皇后是『深情共情、直觉深沉』的情感成熟——但她的关键在于『像深海一样丰盈却有容器盛着，不泛滥』；她的逆位正是『过度自我牺牲、在照顾别人中掏空自己、被情绪淹没』。",
