        "question": "有人要帮我/给我资源，但我隐约觉得这份帮助带着某种条件或掌控，我该接受吗？",
        "domain": "career",
        "step1_energy": "第一步·抓核心能量：星币六正位是公平、不带控制的慷慨流动，而它的逆位正是『带着权力和附加条件的给予、不平等的施舍』。",
        "step2_projection": "第二步·投射到领域：放到你『觉得帮助带着条件或掌控』的处境上——星币六的天平和『施者站着、受者跪着』的画面恰恰对应你的直觉：给予背后可能藏着权力关系。你隐约的不安，可能是察觉到这份帮助不在公平的天平上，而是带着让你亏欠、听话或受制的钩子。",
        "step3_action": "第三步·落地建议：给你的行动是——先把这份帮助放到星币六的天平上称一称：接受它，我需要付出什么隐性的代价(自主、话语权、人情债)？这个代价公平吗？如果这是真心、公平的援助，坦然接受、日后适当回馈即可；如果你的直觉持续指向『有掌控、有钩子』，那就有权谨慎——礼貌地保持边界，或只接受你能对等回报的部分。星币六提醒：健康的给予让你自由，附条件的施舍让你欠债——分清楚，别为一时的资源跪下去。"
