        "step1_energy": "第一步·抓核心能量：星币七是『停下来评估长期投入的成果』——它同时说两件事：真正的收获需要耐心(别拔苗)，但耐心不等于在不结果的地里盲目死守。",
        "step2_projection": "第二步·投射到领域：放到你『投入很久没看到成果』的处境上——星币七几乎就是你此刻该做的动作：像那个拄锄的农夫一样，先停下埋头的劳作，好好端详藤上的星币(评估成果)。这张牌的出现本身就在提示：现在是复盘节点，不是继续闷头干、也不是冲动放弃的时候。",
        "step3_action": "第三步·落地建议：所以给你的行动是——做一次诚实的评估(而非凭情绪决定)：这块地的『土壤』扎实吗(方法、方向对不对)？藤上有没有正在长的星币(哪怕微小、还没成熟的进展)？如果根基扎实、成果在慢慢结、只是需要时间——那星币七要你拿出耐心继续(很多丰收就毁在收获前的放弃)；如果诚实地看，投入很久却毫无进展、方向本身有问题——那它也支持你及时调整，别在不结果的地里再耗。关键是：先评估，再决定，别在焦虑里瞎坚持或瞎放弃。"
