        "step2_projection": "第二步·投射到领域：放到你『急着要结果、慢一点就想放弃』的处境上——你正卡在星币七的逆位：藤上的星币需要一整个生长季才成熟，而你每隔几天就去摇一摇、嫌它长得慢，甚至想连根拔了重种。这种急，恰恰是收获最大的敌人——因为几乎所有有价值的成果，都长在『土元素的慢』里。",
        "step3_action": "第三步·落地建议：给你的行动是——学星币七农夫的姿态：种下之后，把『天天盯着结果』换成『定期(而非时刻)评估 + 持续浇灌』。具体上：给你的努力设一个合理的『生长周期』(比如三个月再评估，而非每天焦虑)，期间专注在能控制的耕耘上，而非无法控制的成熟速度上。提醒自己：成长和复利都是非线性的，很多进展在临界点前看不见。耐心不是被动等待，而是相信扎实的耕耘会在它自己的时间结果——别在花苞期就断定它不会开。"
