        "step1_energy": "第一步·抓核心能量：星币八正位是专注深耕、精益求精，而它的逆位正是『缺乏专注、浅尝辄止、什么都做一点却不深入』。",
        "step2_projection": "第二步·投射到领域：放到你『什么都会一点但都不精』的处境上——你正处在星币八的逆位：你有投入的意愿，但注意力像撒胡椒面一样分散在很多事上，没有在任何一枚星币上雕够深。星币八告诉你，广度不等于精通，真正的价值和成果来自专注的深度。",
        "step3_action": "第三步·落地建议：给你的行动是——学星币八工匠的『收束专注』：从你会的这些里，挑一到两个你最想精通、最有价值的，把原本分散的精力集中投到它们上面，其余暂时放下。给自己一段刻意深耕的时间(而非又去学新东西)，把这一门从『会一点』雕到『拿得出手』。精通带来的成果和底气，是浅尝辄止永远给不了的。先在一枚星币上雕到底，你会尝到深度的甜头。"
