        "step1_energy": "第一步·抓核心能量：星币十是走向长久、稳定、有家庭根基的关系——它代表关系的终极踏实形态：共建可以栖居和延续的『家』。",
        "step2_projection": "第二步·投射到领域：放到你们『考虑长期承诺又怕责任』的处境上——星币十是这个议题上非常正向的牌：它描绘的正是你们可能走向的圆满——稳固的家、几代人的安稳、可传承的根基。你的『怕』，一部分是对这份重量的正常敬畏，一部分可能是逆位提示的『根基是否够稳』的疑虑。",
        "step3_action": "第三步·落地建议：给你的行动是——先分清『健康的郑重』和『根基的隐忧』：走向星币十的圆满，责任是真实的(它值得你郑重对待，而非逃避)；但如果你的怕来自『我们的地基还不够稳』(价值观、财务观、共同规划没谈拢)，那就先补地基再谈仪式——星币十的逆位正是家业因钱财、期待而生的纷争。具体上：和伴侣坦诚聊聊你们对『共同的家』的长远想象(钱怎么管、责任怎么分、要走向什么样的未来)。当根基谈扎实了，那份『怕』会转成『一起建造』的踏实感。真正的长久承诺，不是靠冲动，而是靠共同扎下的根。"
