        "step3_action": "第三步·落地建议：所以给你的行动是——像握住那把剑一样，逼自己把问题『切』清楚：把纠结写下来，剥掉情绪，只问『事实是什么？我真正要决定的是哪一件事？最诚实的答案是什么？』宝剑一相信你有能力看清——很多纠结在被诚实地摊开、理性地切开后，答案会自己显现。但也记得剑有两刃：看清后温柔地对己对人，别用这份清醒去苛责。"
