        "step2_projection": "第二步·投射到领域：放到你『该说清却怕伤感情』的处境上——宝剑一支持你把话摊开(含糊和回避只会让迷雾更浓)，但它的双刃恰恰提醒了你的担心是有道理的：真相怎么说，决定它是解放还是伤害。问题不在『要不要说清』，而在『怎么用好这把剑』。",
        "step3_action": "第三步·落地建议：给你的行动是——鼓起勇气把话说清楚(宝剑一不赞成一直含糊回避)，但握剑时带着分寸：陈述事实和你的真实感受，而不是用尖锐的话去指责或论输赢(那是逆位的『用言语伤人』)。清晰 ≠ 冷酷。真正的宝剑一之力，是既诚实又不失温度地把真相说出来——它会让关系更清明，而非受伤。"
