        "step3_action": "第三步·落地建议：给你的行动是——主动摘下蒙眼布，温和但清楚地把问题摊开(宝剑二的逆位正是『打破僵局、看清真相』的解脱)。不必是激烈的对峙，而是诚实地说出你观察到的、感受到的。回避维持的平静是假的、易碎的；真正的安稳来自看清后共同面对。装作没事最大的风险是——问题不会消失，只会在沉默里长大。"
