        "step3_action": "第三步·落地建议：所以给你的行动是——先松动那个『我没有任何办法』的绝对念头(它就是蒙眼布)。具体做一件事：把处境写下来，然后强迫自己列出『哪怕再小、再不完美的选项』至少三个——你会发现剑阵是有缺口的。绝望往往来自蒙着眼断定没路，而不是真的没路。摘下蒙眼布、朝那个哪怕泥泞的方向先迈一小步，无力感就会开始松动。如果这种被困感很深很久，也值得找人一起帮你看见出口。"
