        "step1_energy": "第一步·抓核心能量：宝剑八的核心正是这种『我没得选』的受困感，而它温柔地反驳：那多半是恐惧设的限，剑阵其实留着缺口。",
        "step2_projection": "第二步·投射到领域：放到你『我没得选、离开就完了』的信念上——宝剑八几乎是在直接跟这句话对话：『没得选』和『离开就完了』很可能就是那块蒙眼布和那圈看似围死的剑。恐惧特别擅长把『很难、有代价』夸大成『完全不可能』，让你觉得自己被彻底钉死在原地。",
        "step3_action": "第三步·落地建议：给你的行动是——把笼统的恐惧拆成具体的事实来检验：『离开我就完了』——具体会发生什么？哪些是真实的困难(需要规划应对)，哪些只是恐惧的想象？通常你会发现，路是有的，只是难走(泥泞)、有代价，但绝非『没得选』。宝剑八不是让你鲁莽跳出去，而是先摘下『我别无选择』的蒙眼布，看清你真实拥有的选项——哪怕只是先为离开做准备的一小步。看见选择，就是重获力量的开始。"
