        "step3_action": "第三步·落地建议：所以给你的行动是——保留骑士的冲劲，但花很短的时间给它装上方向盘：这个目标值得冲吗？最坏情况我扛得住吗？第一步具体怎么走？想清楚这三点（不用想到万无一失，那会浇灭火），然后就大胆冲出去。骑士的智慧是『带着方向的果断』，而不是『鲁莽』或『被劝到不敢动』。"
