        "step2_projection": "第二步·投射到领域：放到你『开头猛、后劲不足』的模式上——你活出的正是权杖骑士的两面：起跑时那股冲劲是真本事（很多人连这一步都迈不出），但你反复卡在逆位的『冲一阵就熄火』上。骑士不缺点火的能力，缺的是把火烧持久的耐力。",
        "step3_action": "第三步·落地建议：给你的行动是——接受你就是个『冲刺型』选手，然后用结构补足耐力：把长目标拆成一段段短冲刺（骑士擅长短程爆发），每段之间给自己明确的补给和小奖励。同时在热情最高时，先建立一个『没热情也能维持』的最低日常动作。别指望靠意志硬撑——那不是骑士的打法；用一次次可完成的小冲刺，替代一次注定熄火的长途。"
