          "investment": "选择长时间、低风险的投资工具，会是你稳定获利的最佳方式，只要能长期累积下来，也会是一笔很可观的收入。",
          "purchasing": "这个时候应该相信你的直觉，只要你觉得有问题的东西就要放弃，不要被别人的意见左右，要对你自己多一点信心。"
