        "step3_action": "第三步·落地建议：所以给你的行动是——把注意力从『怎么压过别人』转到『怎么活出自己的光』：真诚地展现你擅长和热爱的东西、大方地鼓励和照亮身边人、忠于自己的风格而不迎合。当你自己发光又温暖时，存在感是自然吸引来的，不需要靠气势去抢。这就是权杖皇后的魅力逻辑。"
