        "step2_projection": "第二步·投射到领域：放到你『容易嫉妒、没底气』的状态上——你正处在权杖皇后的逆位：内在那团本该温暖照亮自己的火，因为缺乏安全感而向外烧成了对别人的嫉妒。嫉妒的根，往往是自己的光被自己怀疑熄灭了。",
        "step3_action": "第三步·落地建议：给你的行动是——把向外比较的目光收回到自己身上：先重新点亮自己的光(找回你擅长、热爱、让你发亮的事，哪怕小)。权杖皇后的解药不是『别嫉妒』，而是『自己足够暖、足够亮，就不需要盯着别人的光』。像向日葵一样，先忠实地朝向属于你自己的太阳。"
